// Strips the "Generated by Claude Code" footer from pull request descriptions, the no-AI-trailer rule the trailer check
// holds commits to, for descriptions. A cloud session's GitHub connection appends the footer to every description it writes
// and puts it back when the session removes it, so the repository removes it instead. checks.yml runs this file from
// devkit at the caller's pin on each opened, reopened or edited pull request, and by hand (workflow_dispatch) over every
// pull request. An edit made with the workflow's GITHUB_TOKEN starts no new run, so
// there is no loop.
//
// NO node_modules IMPORTS: the job runs without npm ci.

// The footer as the connection writes it: a rule, then one italic line linking Claude Code, at the end of the
// description. Also the "Generated with Claude Code" wording. Read line by line from the end, never with a pattern that
// spans whitespace: a description of 100,000 spaces took twelve seconds under the single regular expression this was.
const FOOTER_LINE = /^_?(?:🤖\s*)?_?Generated (?:by|with) \[Claude Code\]\([^)]*\)_?$/u;
const RULE_LINE = /^-{3,}$/;
// A session link left on its own line.
const SESSION_LINK = /^https:\/\/claude\.ai\/code\/session_[A-Za-z0-9]+$/;

/** The description without the footer, or null when it carries none. @param {unknown} body @returns {string | null} */
export function stripFooter(body) {
  if (typeof body !== "string") return null;
  const lines = body.split("\n");
  let removed = false;
  // A session link and a footer can stack, each under the other; four layers is more than the connection writes.
  for (let layer = 0; layer < 12; layer++) {
    let end = lines.length;
    while (end > 0 && lines[end - 1].trim() === "") end--;
    const last = end > 0 ? lines[end - 1].trim() : "";
    if (FOOTER_LINE.test(last)) {
      let rule = end - 1;
      while (rule > 0 && lines[rule - 1].trim() === "") rule--;
      if (rule > 0 && RULE_LINE.test(lines[rule - 1].trim())) lines.length = rule - 1;
      else if (end > 1) lines.length = end - 1;
      else break;
    } else if (SESSION_LINK.test(last) && end > 1) lines.length = end - 1;
    else break;
    removed = true;
  }
  return removed ? `${lines.join("\n").trimEnd()}\n` : null;
}

/** @param {string} path @param {RequestInit} [init] */
async function gh(path, init = {}) {
  const res = await fetch(`https://api.github.com${path}`, {
    ...init,
    headers: {
      Authorization: `Bearer ${process.env.GITHUB_TOKEN}`,
      Accept: "application/vnd.github+json",
      "Content-Type": "application/json",
    },
  });
  if (!res.ok)
    throw new Error(
      `${init.method ?? "GET"} ${path}: ${res.status} ${(await res.text()).slice(0, 200)}`,
    );
  return res.json();
}

/** @param {string} repo @param {string | number} number @param {unknown} body */
async function fix(repo, number, body) {
  const stripped = stripFooter(body);
  if (stripped === null) return false;
  await gh(`/repos/${repo}/pulls/${number}`, {
    method: "PATCH",
    body: JSON.stringify({ body: stripped }),
  });
  return true;
}

async function main() {
  const repo = process.env.GITHUB_REPOSITORY;
  if (!repo || !process.env.GITHUB_TOKEN)
    throw new Error("GITHUB_REPOSITORY and GITHUB_TOKEN are required");
  const one = process.env.PR_NUMBER;
  if (one) {
    const pr = await gh(`/repos/${repo}/pulls/${one}`);
    console.log(`#${one}: ${(await fix(repo, one, pr.body)) ? "footer removed" : "no footer"}`);
    return;
  }
  let read = 0;
  let fixed = 0;
  for (let page = 1; page <= 50; page++) {
    const prs = await gh(`/repos/${repo}/pulls?state=all&per_page=100&page=${page}`);
    for (const pr of prs) {
      read++;
      if (await fix(repo, pr.number, pr.body)) fixed++;
    }
    if (prs.length < 100) break;
  }
  console.log(`${read} pull request(s) read, ${fixed} footer(s) removed`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((err) => {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  });
}
